package com.aoo.bcg.gamespi.fsm;
import static org.junit.jupiter.api.Assertions.*;import java.time.Duration;import java.util.List;import org.junit.jupiter.api.Test;
class AutomaticTransitionCycleGuardTest{enum State{OPERATE,PASS,TIMEOUT,ROUND_END}@Test void rejectsZeroDelayAutomationButAllowsScheduledCycle(){var zero=List.of(new AutomaticTransitionCycleGuard.Edge<>(State.OPERATE,State.PASS,Duration.ZERO,"auto-pass"),new AutomaticTransitionCycleGuard.Edge<>(State.PASS,State.OPERATE,Duration.ZERO,"next-seat"));assertThrows(IllegalStateException.class,()->AutomaticTransitionCycleGuard.requireNoZeroDelayCycle(zero));var scheduled=List.of(new AutomaticTransitionCycleGuard.Edge<>(State.OPERATE,State.TIMEOUT,Duration.ofSeconds(1),"timeout"),new AutomaticTransitionCycleGuard.Edge<>(State.TIMEOUT,State.OPERATE,Duration.ZERO,"next-seat"));assertDoesNotThrow(()->AutomaticTransitionCycleGuard.requireNoZeroDelayCycle(scheduled));}}
